package fable.hideseek.imba.client;import fable.hideseek.imba.ImbaExtension;import fable.hideseek.imba.game.OverlayBarrierRuntime;import net.fabricmc.fabric.api.client.rendering.v1.WorldRenderEvents;import net.minecraft.client.MinecraftClient;import net.minecraft.util.math.Box;public final class OverlayBarrierRenderer{private OverlayBarrierRenderer(){}public static void register(){WorldRenderEvents.AFTER_ENTITIES.register(ctx->{MinecraftClient client=MinecraftClient.getInstance();if(client.world==null||client.player==null||ctx.matrixStack()==null||ctx.consumers()==null)return;boolean editing=client.player.getMainHandStack().isOf(ImbaExtension.OVERLAY_BARRIER)||client.player.getOffHandStack().isOf(ImbaExtension.OVERLAY_BARRIER);if(!editing)return;String world=client.world.getRegistryKey().getValue().toString();var camera=client.gameRenderer.getCamera().getPos();for(var e:OverlayBarrierRuntime.clientSnapshot()){if(!world.equals(e.world))continue;if(client.player.squaredDistanceTo(e.x+.5D,e.y+.5D,e.z+.5D)>48D*48D)continue;WorldDebugBoxRenderer.drawWorldBox(ctx.matrixStack(),ctx.consumers(),camera,new Box(e.x,e.y,e.z,e.x+1,e.y+1,e.z+1).expand(.002D),255,60,220,255);}});}}
